### Pattern 6: The State Reducer Pattern
Inverts control over state logic transitions. The component exposes a `stateReducer` prop, allowing external consumers to intercept, modify, or override state changes before they are applied.

```javascript
function useToggleWithStateReducer({ customStateReducer } = {}) {
  const defaultReducer = (state, action) => {
    switch (action.type) {
      case 'TOGGLE':
        return { on: !state.on };
      default:
        return state;
    }
  };

  // Combine default reducer with custom consumer reducer
  const combinedReducer = (state, action) => {
    const nextState = defaultReducer(state, action);
    if (customStateReducer) {
      return customStateReducer(state, { ...action, changes: nextState });
    }
    return nextState;
  };

  return useReducer(combinedReducer, { on: false });
}

// Usage: Consumer intercepts state transitions
function App() {
  const [state, dispatch] = useToggleWithStateReducer({
    customStateReducer: (currentState, action) => {
      // Custom Rule: Disallow toggling OFF on Wednesdays
      const isWednesday = new Date().getDay() === 3;
      if (isWednesday && !action.changes.on) {
        return currentState; // Block transition, return current state
      }
      return action.changes; // Allow transition
    }
  });

  return (
    <button onClick={() => dispatch({ type: 'TOGGLE' })}>
      State: {state.on ? "ON" : "OFF"}
    </button>
  );
}
```

